with.command:
set -eu
# The two words the whole round rests on, read by Sailor and not by the
# engine that wrote them: a repair that reproduced nothing repaired
# nothing, and a rule drawn from it would be read as an instruction.
[ "$REPRODUCED" = true ] || { echo "the fault was never seen red: nothing here was reproduced" >&2; exit 1; }
[ "$FIXED" = true ] || { echo "the fault is not closed: the test is not green after the change" >&2; exit 1; }
# Then the tree, not the answer: the acceptance fixed at launch runs here.
sh -c "$CHECK" || { echo "the acceptance is red on the tree: the fault is not closed" >&2; exit 1; }
